function home(){setSEO("Home","CUS Trento C5: sito demo per futsal universitario con news, rosa, calendari e match center.");const next=nextFixture(state.fixtures);const last=lastResult(state.fixtures);const cus=state.standings.find(s=>s.team==="CUS Trento")||{};const top=[...state.roster].sort((a,b)=>b.goals-a.goals)[0]||{};const pinned=latestNews(state.news);const cupNext=nextFixture(state.cup.fixtures);app.innerHTML=`<section class="hero"><div class="container hero-grid"><div><span class="tag">Serie C1</span><span class="tag ghost">Season 25/26</span><h1>More than a team. <span class="red">Trento</span> plays fast.</h1><p class="lead">News, match center, rosa, classifica, coppa, U21, video, gallery e sponsor in un sito più vicino a una piattaforma reale.</p><div class="btns"><button class="btn" onclick="route('fixtures')">Prossima partita →</button><button class="btn light" onclick="route('squad')">Scopri la rosa</button><button class="btn ghost" onclick="route('matchday')">Info matchday</button></div></div><div><div class="match-card"><div class="kicker">Next match</div><div class="match-teams"><div><div class="clubmark">${next.home.includes("CUS")?"CUS":next.home.slice(0,2)}</div><b>${next.home}</b></div><div><small>${fmt(next.date)}</small><div class="timebox">${next.time}</div></div><div><div class="clubmark">${next.away.includes("CUS")?"CUS":next.away.slice(0,2)}</div><b>${next.away}</b></div></div></div><div class="mini-grid"><div class="mini"><strong>#${cus.pos||"-"}</strong><span>Posizione</span></div><div class="mini"><strong>${top.goals||0}</strong><span>Top scorer<br>${top.name||""}</span></div><div class="mini"><strong>${last.score||"-"}</strong><span>Ultimo risultato</span></div></div></div></div></section><section class="section"><div class="container grid grid-2"><article class="card feature clickable" onclick="route('article-${pinned.id}')"><img loading="lazy" decoding="async" src="${pinned.image}" alt="${pinned.title}"><div class="card-pad"><span class="badge">${pinned.category}</span><h2 style="margin-top:14px">${pinned.title}</h2><p class="muted">${pinned.excerpt}</p><button class="btn dark">Leggi articolo</button></div></article><article class="cup-highlight"><span class="eyebrow" style="background:white;color:#09090b">Coppa</span><h2 style="font-size:34px;margin:0">${state.cup.title}</h2><p style="color:rgba(255,255,255,.75)">Stato: <b>${state.cup.status}</b></p>${cupFixture(cupNext,true)}<button class="btn ghost" style="margin-top:16px" onclick="route('coppa')">Vai alla Coppa</button></article></div></section><section class="section" style="padding-top:0"><div class="container grid grid-3"><div class="card card-pad"><h2>Calendario</h2>${state.fixtures.slice(0,3).map(fixtureRow).join("")}</div><div class="card card-pad"><h2>Classifica</h2>${state.standings.slice(0,5).map(standingMini).join("")}</div><div class="card card-pad"><h2>Social wall</h2>${socialPosts()}</div></div></section>${footer()}`;}
