function news(){const cats=["Tutte",...new Set(state.news.map(n=>n.category))];shell("Media center","News, match report e storie dal club",`<div class="toolbar">${cats.map(c=>`<button class="pill newsf ${c==="Tutte"?"active":""}">${c}</button>`).join("")}</div><div class="grid grid-3" id="newsGrid">${newsCards(state.news)}</div>`,`<div class="search">⌕ <input oninput="searchNews(this.value)" placeholder="Cerca news" aria-label="Cerca news"></div>`,"News, articoli e match report CUS Trento C5.");document.querySelectorAll(".newsf").forEach(b=>b.onclick=function(){document.querySelectorAll(".newsf").forEach(x=>x.classList.remove("active"));this.classList.add("active");const c=this.textContent;$("#newsGrid").innerHTML=newsCards(c==="Tutte"?state.news:state.news.filter(n=>n.category===c));});}
