function filterSquad(){const team=document.querySelector(".teamf.active").textContent,role=document.querySelector(".rolef.active").textContent;$("#squadGrid").innerHTML=players(state.roster.filter(p=>(team==="Tutte"||p.team===team)&&(role==="Tutti"||p.role===role)));}
function playerDetail(id){const p=state.roster.find(x=>String(x.id)===String(id));if(!p){route("squad");return;}const rows=(p.history||[]).map(h=>`<tr><td>${h.season}</td><td>${h.team}</td><td>${h.appearances}</td><td>${h.goals}</td><td>${h.assists}</td></tr>`).join("");const comps=p.competitions||{campionato:{appearances:p.appearances,goals:p.goals,assists:p.assists},coppa:{appearances:0,goals:0,assists:0},totale:{appearances:p.appearances,goals:p.goals,assists:p.assists}};const split=Object.entries(comps).map(([k,v])=>({label:k[0].toUpperCase()+k.slice(1),...v}));const gk=p.goalkeeperStats;const gkBlock=gk?`<div class="gk-panel"><span class="eyebrow" style="background:white;color:#09090b">Goalkeeper analytics</span><h2 style="font-size:34px;margin:0 0 18px">Statistiche portiere</h2><div class="gk-grid"><div class="gk-box"><b>${gk.cleanSheets}</b><span>Clean sheet</span></div><div class="gk-box"><b>${gk.saves}</b><span>Parate</span></div><div class="gk-box"><b>${gk.goalsAgainst}</b><span>Gol subiti</span></div><div class="gk-box"><b>${gk.goalsAgainstAvg}</b><span>Media subiti</span></div><div class="gk-box"><b>${gk.penaltiesSaved}</b><span>Rigori parati</span></div><div class="gk-box"><b>${gk.saveRate}%</b><span>Save rate</span></div><div class="gk-box"><b>${gk.minutes}</b><span>Minuti</span></div><div class="gk-box"><b>${gk.appearances}</b><span>Presenze</span></div></div></div>`:"";shell("Player profile",p.name,`<div class="breadcrumb"><button class="tiny" onclick="route('squad')">← Torna alla rosa</button><span>/ #${p.number} / ${p.role}</span></div><div class="player-hero"><aside class="player-portrait"><span class="eyebrow" style="background:white;color:#09090b">${p.team}</span><img loading="lazy" decoding="async" src="${p.photo}" alt="${p.name}"><h2 style="font-size:42px;line-height:.9;margin:22px 0 10px">${p.name}</h2><p style="color:rgba(255,255,255,.76)">${p.bio}</p></aside><section class="grid"><div class="grid grid-4"><div class="stat-tile"><b>#${p.number}</b><span>Numero</span></div><div class="stat-tile"><b>${p.appearances}</b><span>Presenze</span></div><div class="stat-tile"><b>${p.goals}</b><span>Reti</span></div><div class="stat-tile"><b>${p.assists}</b><span>Assist</span></div></div>${gkBlock}<div class="card card-pad"><h2>Statistiche per competizione</h2><div class="split-stat" style="margin-top:18px">${split.map(s=>`<div class="split-box"><h3>${s.label}</h3><div class="metrics"><div class="metric"><b>${s.appearances}</b><small>Pres</small></div><div class="metric"><b>${s.goals}</b><small>Reti</small></div><div class="metric"><b>${s.assists}</b><small>Assist</small></div></div></div>`).join("")}</div></div><div class="card card-pad table-wrap"><h2>Storico stagioni</h2><table class="profile-table" style="margin-top:16px"><thead><tr><th>Stagione</th><th>Squadra</th><th>Presenze</th><th>Reti</th><th>Assist</th></tr></thead><tbody>${rows}</tbody></table></div></section></div>`,"Scheda giocatore, presenze, reti, assist e statistiche portiere.",p.photo);}
function normalizeMatchForCalendar(f, type){return {...f, competition:type||f.competition||f.round, _calendarType:type||f.competition||f.round};}
function calendarSource(){
  if(view.calendar==="u21") return [...(state.u21Fixtures||[]).map(f=>normalizeMatchForCalendar(f,"Campionato")), ...(((state.u21Cup||{}).fixtures||[]).map(f=>normalizeMatchForCalendar(f,"Coppa")))];
  return [...(state.fixtures||[]).map(f=>normalizeMatchForCalendar(f, f.competition==="Playoff"?"Playoff":(f.competition==="Serie C1"||f.competition==="Campionato"?"Campionato":f.competition))), ...(((state.cup||{}).fixtures||[]).map(f=>normalizeMatchForCalendar(f,"Coppa")))];
}
function matchCalendarFilter(f, filter){
  if(filter==="Tutte") return true;
  if(filter==="Da giocare"||filter==="Terminata") return f.status===filter;
  if(filter==="Campionato") return f._calendarType==="Campionato" || ["Serie C1","Under 21","Campionato"].includes(f.competition);
  if(filter==="Coppa") return f._calendarType==="Coppa" || f.competition==="Coppa";
  if(filter==="Playoff") return f._calendarType==="Playoff" || f.competition==="Playoff";
  return true;
}
function calendarPageButtons(totalPages){
  if(totalPages<=1) return "";
  return `<div class="pagination">${Array.from({length:totalPages},(_,i)=>i+1).map(n=>`<button class="${view.calendarPage===n?'active':''}" onclick="setCalendarPage(${n})">${n}</button>`).join("")}</div>`;
}
function setCalendarFilter(filter){view.calendarFilter=filter;view.calendarPage=1;renderCalendarList();}
function setCalendarPage(page){view.calendarPage=page;renderCalendarList();}
function renderCalendarList(){
  const perPage=5;
  const filtered=calendarSource().filter(f=>matchCalendarFilter(f,view.calendarFilter)).sort((a,b)=>new Date(a.date)-new Date(b.date));
  const totalPages=Math.max(1,Math.ceil(filtered.length/perPage));
  if(view.calendarPage>totalPages)view.calendarPage=totalPages;
  const start=(view.calendarPage-1)*perPage;
  const pageItems=filtered.slice(start,start+perPage);
  const target=$("#fixGrid");
  if(target) target.innerHTML=`${pageItems.map(fixtureRow).join("")||"<div class='card card-pad'><p class='muted'>Nessuna partita trovata.</p></div>"}${calendarPageButtons(totalPages)}`;
}
function fixtures(){const team=view.calendar==="u21"?"Under 21":"Prima squadra";shell("Match center",`Calendario — ${team}`,`${teamSwitch("calendar")}<div class="toolbar">${["Tutte","Da giocare","Terminata","Campionato","Coppa","Playoff"].map(f=>`<button class="pill fixf ${view.calendarFilter===f?"active":""}" onclick="setCalendarFilter('${f}')">${f}</button>`).join("")}</div><div class="grid" id="fixGrid"></div>`,"","Calendario e risultati CUS Trento C5.");renderCalendarList();}
function matchDetail(id){const f=[...state.fixtures,...state.u21Fixtures,...state.cup.fixtures.map(x=>({...x,competition:"Coppa"})),...((state.u21Cup||{}).fixtures||[]).map(x=>({...x,competition:"Coppa"}))].find(x=>String(x.id)===String(id));if(!f){route("fixtures");return;}const lineup=f.lineup||{module:"3-1",startingFive:[],bench:[],absent:[],suspended:[],injured:[],tacticalNotes:[]};const starters=lineup.startingFive||[];const spots=["gk","p1","p2","p3","p4"];const timeline=(f.timeline||[]).map(e=>`<div class="event-item"><div class="event-minute">${e.minute}</div><div><b>${e.team||""}</b><p class="muted" style="margin:4px 0 0">${e.text}</p></div></div>`).join("");shell("Match center",`${f.home} - ${f.away}`,`<div class="breadcrumb"><button class="tiny" onclick="route('fixtures')">← Torna al calendario</button><span>${fmt(f.date)} · ${f.time} · ${f.venue}</span></div><div class="grid grid-2"><div class="cup-highlight"><span class="eyebrow" style="background:white;color:#09090b">${f.competition||f.round}</span><div class="match-teams"><div><div class="clubmark">${f.home.includes("CUS")?"CUS":f.home.slice(0,2)}</div><b>${f.home}</b></div><div><div class="timebox">${f.score||"VS"}</div><small>${f.status}</small></div><div><div class="clubmark">${f.away.includes("CUS")?"CUS":f.away.slice(0,2)}</div><b>${f.away}</b></div></div><p style="color:rgba(255,255,255,.72)">${f.summary||"Dettaglio partita in aggiornamento."}</p></div><div class="card card-pad"><h2>Tabellino</h2><div class="grid grid-2" style="margin-top:18px"><div><b>Marcatori</b><p class="muted">${(f.scorers||[]).join(", ")||"Da definire"}</p></div><div><b>MVP</b><p class="muted">${f.mvp||"Da definire"}</p></div><div><b>Ammoniti</b><p class="muted">${(f.yellow||[]).join(", ")||"Nessuno"}</p></div><div><b>Espulsi</b><p class="muted">${(f.red||[]).join(", ")||"Nessuno"}</p></div></div></div></div><div class="grid grid-4" style="margin-top:22px">${["shots","shotsAgainst","possession","corners"].map(k=>`<div class="stat-tile"><b>${(f.stats&&f.stats[k])||0}${k==="possession"?"%":""}</b><span>${{shots:"Tiri",shotsAgainst:"Tiri subiti",possession:"Possesso",corners:"Corner"}[k]}</span></div>`).join("")}</div><div class="grid grid-2" style="margin-top:22px"><div class="lineup-board"><span class="eyebrow" style="background:white;color:#09090b">Tattica</span><h2 style="font-size:34px;margin:0">Modulo ${lineup.module}</h2><div class="pitch">${starters.slice(0,5).map((name,i)=>`<div class="spot ${spots[i]||"p4"}">${name}</div>`).join("")}</div></div><div class="card card-pad"><h2>Convocati e note tattiche</h2><div class="grid grid-2" style="margin-top:18px"><div><b>Quintetto</b><p class="muted">${starters.join(", ")||"Da definire"}</p></div><div><b>Panchina</b><p class="muted">${(lineup.bench||[]).join(", ")||"Da definire"}</p></div><div><b>Assenti</b><p class="muted">${(lineup.absent||[]).join(", ")||"Nessuno"}</p></div><div><b>Squalificati / infortunati</b><p class="muted">${[...(lineup.suspended||[]),...(lineup.injured||[])].join(", ")||"Nessuno"}</p></div></div><h2 style="margin-top:20px">Game plan</h2>${(lineup.tacticalNotes||[]).map(n=>`<p class="muted">• ${n}</p>`).join("")}</div></div><div class="grid grid-2" style="margin-top:22px"><div class="card card-pad"><h2>Timeline eventi</h2><div class="event-list" style="margin-top:18px">${timeline||"<p class='muted'>Timeline in aggiornamento.</p>"}</div></div><div class="card card-pad"><h2>Media partita</h2><div class="grid">${state.gallery.slice(0,2).map(g=>`<article class="card gallery-card"><img loading="lazy" class="gallery-img" src="${g.image}" alt="${g.title}"><div class="gallery-caption"><span class="badge">${g.category}</span><h2>${g.title}</h2></div></article>`).join("")}</div></div></div>`,"Dettaglio partita, formazione, tattica, tabellino e statistiche.");}
function cupFixture(f,compact=false){if(!f)return "";return compact?`<div style="margin-top:16px"><div class="fixture" style="background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.18);color:white"><div class="fixture-top" style="color:rgba(255,255,255,.7)"><span>${f.round} · ${fmt(f.date)}</span><span>${f.status}</span></div><div class="teams"><span>${f.home}</span><span class="score">${f.score||"VS"}</span><span>${f.away}</span></div><p style="color:rgba(255,255,255,.7)">${f.venue}</p></div></div>`:fixtureRow({...f,competition:f.round});}
function coppa(){const cupData=view.cup==="u21"?state.u21Cup:state.cup;const rounds=cupData.fixtures;const next=rounds.find(x=>x.status==="Da giocare")||rounds[0];const team=view.cup==="u21"?"Under 21":"Prima squadra";shell("Cup",`Coppa — ${team}`,`${teamSwitch("cup")}<div class="grid grid-2"><div class="cup-highlight"><span class="eyebrow" style="background:white;color:#09090b">${cupData.edition}</span><h2 style="font-size:42px">${cupData.title}</h2><p style="color:rgba(255,255,255,.78)">Percorso attuale: <b>${cupData.status}</b></p>${cupFixture(next,true)}</div><div class="card card-pad"><h2>Road to the final</h2><div class="cup-stage" style="margin-top:20px">${rounds.map(r=>`<div class="stage-card ${(r.round||"").includes("Quarti")?"active":""} clickable" onclick="route('match-${r.id}')"><div class="stage-label">${r.round}</div><div style="font-weight:1000;margin:8px 0 6px">${r.home}</div><div class="score">${r.score||"VS"}</div><div style="font-weight:1000;margin:6px 0 8px">${r.away}</div><div class="muted">${fmt(r.date)} · ${r.time}</div></div>`).join("")}</div></div></div><div class="section" style="padding-bottom:0"><div class="grid">${rounds.map(r=>cupFixture(r,false)).join("")}</div></div>`,"","Percorso in Coppa CUS Trento C5.");}
function u21(){const u21players=state.roster.filter(p=>p.team==="Under 21");shell("Under 21","Settore giovanile: rosa, calendario e classifica",`<div class="grid grid-3"><div class="stat-tile"><b>${u21players.length}</b><span>Giocatori U21</span></div><div class="stat-tile"><b>${state.u21Standings[0].pts}</b><span>Punti</span></div><div class="stat-tile"><b>${u21players.reduce((s,p)=>s+p.goals,0)}</b><span>Reti rosa</span></div></div><div class="grid grid-2" style="margin-top:22px"><div class="card card-pad"><h2>Calendario U21</h2>${state.u21Fixtures.map(fixtureRow).join("")}</div><div class="card card-pad table-wrap"><h2>Classifica U21</h2><table class="table" style="box-shadow:none;margin-top:16px"><thead><tr><th>#</th><th>Squadra</th><th>PT</th><th>G</th><th>V</th><th>N</th><th>P</th><th>GF</th><th>GS</th><th>DR</th></tr></thead><tbody>${tableRows(state.u21Standings,"CUS Trento U21")}</tbody></table></div></div><h2 style="font-size:38px;margin:34px 0 18px">Rosa U21</h2><div class="grid grid-4">${players(u21players)}</div>`,"","Settore Under 21 del CUS Trento C5.");}
function standings(){const isU21=view.standings==="u21";const table=isU21?state.u21Standings:state.standings;const playersScope=state.roster.filter(p=>isU21?p.team==="Under 21":p.team==="Prima squadra");const scorers=[...playersScope].sort((a,b)=>b.goals-a.goals).slice(0,10);const assists=[...playersScope].sort((a,b)=>b.assists-a.assists).slice(0,10);const title=isU21?"Under 21":"Prima squadra";shell("Tables",`Classifiche — ${title}`,`${teamSwitch("standings")}<div class="grid" style="grid-template-columns:1fr"><div class="card card-pad table-wrap"><h2>Classifica ${title}</h2><table class="table" style="box-shadow:none;margin-top:16px"><thead><tr><th>#</th><th>Squadra</th><th>PT</th><th>G</th><th>V</th><th>N</th><th>P</th><th>GF</th><th>GS</th><th>DR</th></tr></thead><tbody>${tableRows(table,isU21?"CUS Trento U21":"CUS Trento")}</tbody></table></div><div class="grid grid-2"><div class="card card-pad"><h2>Marcatori</h2>${scorers.map((p,i)=>`<div class="list-row clickable" onclick="route('player-${p.id}')"><div><b>${i+1}. ${p.name}</b><div class="muted">${p.team}</div></div><b>${p.goals}</b></div>`).join("")}</div><div class="card card-pad"><h2>Assist</h2>${assists.map((p,i)=>`<div class="list-row clickable" onclick="route('player-${p.id}')"><div><b>${i+1}. ${p.name}</b><div class="muted">${p.team}</div></div><b>${p.assists}</b></div>`).join("")}</div></div></div>`,"","Classifiche Serie C1, Under 21 e ranking giocatori.");}
function barChart(list,key){const max=Math.max(...list.map(p=>p[key]),1);return `<div class="bar-list" style="margin-top:22px">${list.map(p=>`<div class="bar-row"><span>${p.name.split(" ").slice(0,2).join(" ")}</span><div class="bar-track"><div class="bar-fill" style="width:${p[key]/max*100}%"></div></div><b>${p[key]}</b></div>`).join("")}</div>`;}
function stats(){const isU21=view.stats==="u21";const playersScope=state.roster.filter(p=>isU21?p.team==="Under 21":p.team==="Prima squadra");const table=isU21?state.u21Standings:state.standings;const teamRow=table.find(s=>isU21?s.team.includes("CUS Trento U21"):s.team==="CUS Trento")||{};const top=[...playersScope].sort((a,b)=>b.goals-a.goals).slice(0,8),assist=[...playersScope].sort((a,b)=>b.assists-a.assists).slice(0,8);const tg=playersScope.reduce((s,p)=>s+p.goals,0),ta=playersScope.reduce((s,p)=>s+p.assists,0);const title=isU21?"Under 21":"Prima squadra";shell("Analytics",`Statistiche — ${title}`,`${teamSwitch("stats")}<div class="grid grid-4" style="margin-bottom:22px"><div class="stat-tile"><b>${tg}</b><span>Goal giocatori</span></div><div class="stat-tile"><b>${ta}</b><span>Assist</span></div><div class="stat-tile"><b>${teamRow.gf||0}</b><span>Gol fatti</span></div><div class="stat-tile"><b>${(teamRow.gf||0)-(teamRow.gs||0)}</b><span>Differenza reti</span></div></div><div class="grid grid-2"><div class="card card-pad"><h2>Top scorer</h2>${barChart(top,"goals")}</div><div class="card card-pad"><h2>Assist leader</h2>${barChart(assist,"assists")}</div></div>`,"","Statistiche e trend CUS Trento C5.");}
function staff(){const team=view.staff==="u21"?"Under 21":"Prima squadra";const items=state.staff.filter(s=>(s.team||"Prima squadra")===team);shell("Staff",`Staff tecnico — ${team}`,`${teamSwitch("staff")}<div class="grid grid-4">${items.map(s=>`<article class="card"><img loading="lazy" class="staff-photo" src="${s.photo}" alt="${s.name}"><div class="card-pad"><span class="badge">${s.role}</span><h2 style="margin-top:12px">${s.name}</h2><p class="muted">${s.bio}</p></div></article>`).join("")}</div>`,"","Staff tecnico CUS Trento C5.");}
function matchday(){const next=state.fixtures.find(f=>f.status==="Da giocare")||state.fixtures[0];shell("Matchday","Info campo, ingresso e come arrivare",`<div class="grid grid-2"><div class="cup-highlight"><span class="eyebrow" style="background:white;color:#09090b">Next home game</span><h2 style="font-size:42px">${next.home} - ${next.away}</h2><p>${fmt(next.date)} · ${next.time} · ${next.venue}</p><button class="btn ghost" onclick="route('match-${next.id}')">Apri match center</button></div><div class="mapbox"><div><h2 style="font-size:38px;margin:0">Sanbàpolis</h2><p>Via della Malpensada, Trento</p><p>Parcheggi nelle aree limitrofe. Apertura porte 60 minuti prima della gara.</p></div></div></div><div class="grid grid-3" style="margin-top:22px">${["Ingresso libero o secondo comunicazione club","Area studenti e famiglie in tribuna","Contatti social per aggiornamenti live"].map(x=>`<div class="card card-pad"><h2>${x}</h2><p class="muted">Blocco informativo modificabile in produzione dall’admin.</p></div>`).join("")}</div>`,"","Informazioni matchday, campo, orari e accesso.");}
function gallery(){const albums=state.galleryAlbums||[];const cats=["Tutte",...new Set(albums.map(g=>g.category))];shell("Media gallery","Gallery fotografiche",`<p class="muted" style="max-width:760px;margin-top:-8px;margin-bottom:24px">Album placeholder cliccabili. Ogni card apre una gallery reale con poche foto demo, invece di essere una semplice immagine isolata.</p><div class="toolbar">${cats.map(c=>`<button class="pill galf ${c==="Tutte"?"active":""}">${c}</button>`).join("")}</div><div class="grid grid-3" id="galleryGrid">${galleryCards(albums)}</div>`,"","Gallery fotografiche CUS Trento C5.");document.querySelectorAll(".galf").forEach(btn=>btn.onclick=function(){document.querySelectorAll(".galf").forEach(x=>x.classList.remove("active"));this.classList.add("active");const c=this.textContent;$("#galleryGrid").innerHTML=galleryCards(c==="Tutte"?albums:albums.filter(g=>g.category===c));});}
function galleryCards(items){return items.map(g=>`<article class="card gallery-card clickable" onclick="route('gallery-album-${g.id}')"><span class="album-count">${(g.photos||[]).length} foto</span><img loading="lazy" class="gallery-img" src="${g.cover}" alt="${g.title}"><div class="gallery-caption"><span class="badge">${g.category}</span><h2 style="margin-top:10px">${g.title}</h2><p>${fmt(g.date)}</p></div></article>`).join("");}
function galleryAlbum(id){const g=(state.galleryAlbums||[]).find(x=>String(x.id)===String(id));if(!g){route("gallery");return;}shell("Gallery",g.title,`<div class="breadcrumb"><button class="tiny" onclick="route('gallery')">← Torna alle gallery</button><span>${g.category} · ${fmt(g.date)}</span></div><p class="muted" style="max-width:760px">${g.description||""}</p><div class="grid grid-3" style="margin-top:24px">${(g.photos||[]).map((src,i)=>`<article class="card clickable" onclick="openLightbox(${g.id},${i})"><img loading="lazy" class="gallery-img" src="${src}" alt="${g.title} foto ${i+1}"><div class="card-pad"><span class="badge">Foto ${i+1}</span><p class="muted">Clicca per aprire in lightbox</p></div></article>`).join("")}</div>`,"","Album fotografico CUS Trento C5.",g.cover);}
function videos(){shell("Video","Highlights, interviste e contenuti social video",`<div class="grid grid-3">${state.videos.map(v=>`<a class="card clickable" href="${v.url}" target="_blank" rel="noopener"><div style="position:relative"><img loading="lazy" class="video-thumb" src="${v.thumb}" alt="${v.title}"><div class="play">▶</div></div><div class="card-pad"><span class="badge">${v.category}</span><h2 style="margin-top:12px">${v.title}</h2></div></a>`).join("")}</div>`,"","Video e highlights CUS Trento C5.");}
function social(){shell("Social wall","Ultimi contenuti dai canali del club",`<div class="grid grid-3">${state.social.map(s=>`<article class="social-post"><span class="badge">${s.network}</span><h2 style="margin-top:12px">${s.handle}</h2><p class="muted">${s.text}</p><b>${fmt(s.date)}</b></article>`).join("")}</div>`,"","Social wall CUS Trento C5.");}

function tryout(){shell("Provini","Entra nel progetto CUS Trento C5",`<div class="grid grid-2"><div class="tryout-hero"><span class="eyebrow" style="background:white;color:#09090b">Tryout</span><h2 style="font-size:42px">Vuoi giocare con noi?</h2><p style="color:rgba(255,255,255,.74)">Compila la candidatura demo: ruolo, esperienza, università/corso e contatti. In produzione il form invierà la richiesta allo staff tecnico.</p><div class="grid grid-2" style="margin-top:22px">${["Prima squadra","Under 21","Portieri","Studenti UniTrento"].map(x=>`<div class="gk-box"><b>${x}</b><span>Area</span></div>`).join("")}</div></div><div class="lead-form"><h2>Modulo candidatura</h2><div class="form-grid" style="grid-template-columns:1fr 1fr"><label><span>Nome e cognome</span><input id="try_name"></label><label><span>Età</span><input id="try_age" type="number"></label><label><span>Ruolo</span><select id="try_role"><option>Portiere</option><option>Centrale</option><option>Laterale</option><option>Punta</option></select></label><label><span>Università / corso</span><input id="try_university"></label><label><span>Telefono</span><input id="try_phone"></label><label><span>Email</span><input id="try_email" type="email"></label><label style="grid-column:1/-1"><span>Esperienza e note</span><textarea id="try_notes"></textarea></label></div><button class="btn dark" style="margin-top:14px" onclick="saveLead('tryout')">Invia candidatura demo</button></div></div><div class="grid grid-3" style="margin-top:24px">${["Valutazione tecnica","Allenamento di prova","Inserimento nel gruppo"].map((x,i)=>`<div class="card card-pad"><span class="badge">Step 0${i+1}</span><h2 style="margin-top:12px">${x}</h2><p class="muted">Workflow demo per gestire le richieste dei giocatori interessati.</p></div>`).join("")}</div>`,"","Modulo provini e candidature CUS Trento C5.");}

function sponsor(){shell("Partner","Sponsor, partner e community del progetto",`<div class="grid grid-3">${state.sponsors.map(s=>`<article class="card card-pad"><div class="sponsor-logo">${s.logo}</div><div style="margin-top:18px" class="sponsor-tier">${s.tier}</div><h2 style="margin-top:8px">${s.name}</h2><p class="muted">Spazio sponsor configurabile: logo, descrizione, link e livello di partnership.</p><a class="btn soft" href="${s.url}" style="margin-top:10px">Scopri →</a></article>`).join("")}</div><div class="section" style="padding-bottom:0"><span class="eyebrow">Pacchetti sponsor</span><h2 class="title" style="margin-bottom:24px">Visibilità commerciale</h2><div class="grid grid-4">${(state.sponsorPackages||[]).map((p,i)=>`<article class="package-card ${i===0?'featured':''}"><span class="badge">${p.price}</span><h2 style="margin-top:12px">${p.name}</h2><ul>${p.visibility.map(v=>`<li>${v}</li>`).join("")}</ul><button class="btn ${i===0?'ghost':'dark'}" onclick="route('sponsor-lead')">${p.cta}</button></article>`).join("")}</div></div><div class="newsletter" style="margin-top:24px"><span class="eyebrow" style="background:white;color:#09090b">Media kit</span><h2 style="font-size:38px">Richiedi brochure sponsor e proposta di visibilità.</h2><p style="color:rgba(255,255,255,.68)">Ideale per aziende locali, partner universitari e brand sportivi.</p><button class="btn ghost" onclick="route('sponsor-lead')">Richiedi media kit</button></div>`,"","Sponsor e partner CUS Trento C5.");}
function sponsorLead(){shell("Sponsor lead","Richiedi media kit o proposta sponsor",`<div class="grid grid-2"><div class="lead-form"><h2>Richiesta commerciale</h2><div class="form-grid" style="grid-template-columns:1fr"><label><span>Azienda</span><input id="lead_company"></label><label><span>Referente</span><input id="lead_name"></label><label><span>Email</span><input id="lead_email" type="email"></label><label><span>Pacchetto di interesse</span><select id="lead_package">${(state.sponsorPackages||[]).map(p=>`<option>${p.name}</option>`).join("")}</select></label><label><span>Messaggio</span><textarea id="lead_msg"></textarea></label></div><button class="btn dark" style="margin-top:14px" onclick="saveLead('sponsor')">Invia richiesta demo</button></div><div class="cup-highlight"><span class="eyebrow" style="background:white;color:#09090b">Perché sponsorizzare</span><h2 style="font-size:40px">Visibilità locale, universitaria e digitale.</h2><p style="color:rgba(255,255,255,.72)">Il pacchetto può includere logo sito, social content, matchday post, banner, backdrop e iniziative con studenti.</p></div></div>`,"","Lead form sponsor CUS Trento C5.");}
function seasons(){shell("Archive","Archivio stagioni",`<div class="grid grid-3">${state.seasons.map(s=>`<article class="card card-pad"><span class="badge">${s.season}</span><h2 style="margin-top:12px">${s.competition}</h2><div class="metrics"><div class="metric"><b>${s.position}</b><small>Pos</small></div><div class="metric"><b>${s.gf}</b><small>GF</small></div><div class="metric"><b>${s.gs}</b><small>GS</small></div></div><p class="muted">${s.record}</p><p class="muted">${s.note}</p></article>`).join("")}</div>`,"","Archivio stagioni CUS Trento C5.");}
function timeline(){shell("Timeline","Momenti chiave della stagione",`<div class="timeline">${state.timeline.map(t=>`<div class="card card-pad timeline-item"><div class="timeline-date">${t.date}</div><div><h2>${t.title}</h2><p class="muted">${t.text}</p></div></div>`).join("")}</div>`,"","Timeline stagione CUS Trento C5.");}
function records(){shell("Hall of fame","Record e milestone del club",`<div class="grid grid-3">${state.records.map(r=>`<div class="record-card"><span class="eyebrow">${r.label}</span><h2 style="font-size:34px">${r.value}</h2><p style="color:rgba(255,255,255,.68)">${r.detail}</p></div>`).join("")}</div>`,"","Record e hall of fame CUS Trento C5.");}
function contacts(){shell("Contatti","Newsletter, sponsor e provini",`<div class="grid grid-2"><div class="newsletter"><span class="eyebrow" style="background:white;color:#09090b">Newsletter</span><h2 style="font-size:38px">Ricevi aggiornamenti su partite, news e iniziative.</h2><label><span style="color:rgba(255,255,255,.72)">Email</span><input placeholder="nome@email.it"></label><button class="btn ghost" style="margin-top:14px" onclick="alert('Demo: form non collegato a backend')">Iscriviti</button></div><div class="card card-pad"><h2>Scrivici</h2><div class="form-grid" style="grid-template-columns:1fr"><label><span>Nome</span><input></label><label><span>Email</span><input></label><label><span>Motivo</span><select><option>Diventa sponsor</option><option>Provino</option><option>Informazioni partita</option><option>Media</option></select></label><label><span>Messaggio</span><textarea></textarea></label></div><button class="btn dark" style="margin-top:14px" onclick="alert('Demo: form non collegato a backend')">Invia richiesta</button></div></div>`,"","Contatti, newsletter, sponsor e provini.");}
function privacy(){shell("Privacy Policy","Informativa sul trattamento dei dati personali",`
<div class="card card-pad article-body">
  <p class="muted">Ultimo aggiornamento: maggio 2026</p>

  <h2>Titolare del trattamento</h2>
  <p>Il titolare del trattamento dei dati personali raccolti tramite questo sito e' il <b>Centro Universitario Sportivo Trento - A.S.D.</b> (di seguito "CUS Trento").</p>
  <ul>
    <li>P.IVA: 00929160224 - C.F.: 80011170224</li>
    <li>Email di contatto per la privacy: <a href="mailto:privacy@custrentocalcioa5.it">privacy@custrentocalcioa5.it</a></li>
    <li>Sito istituzionale: <a href="https://www.custrento.it" target="_blank" rel="noopener">www.custrento.it</a></li>
  </ul>
  <p>Questo sito (<b>custrentocalcioa5.it</b>) e' dedicato alla sezione Calcio a 5 del CUS Trento. Per il trattamento dati a livello dell'ente si rimanda anche all'informativa ufficiale del CUS Trento, disponibile al fondo di questa pagina.</p>

  <h2>Quali dati raccogliamo</h2>
  <p>Questo sito e' un sito statico: <b>non dispone di un database e non registra automaticamente i dati di navigazione</b>. I dati personali vengono trattati solo nei casi seguenti:</p>
  <ul>
    <li><b>Modulo Provini</b>: quando invii una candidatura, il modulo apre il tuo programma di posta con un'email precompilata indirizzata al club. I dati che decidi di inviare (es. nome, eta', ruolo, universita'/corso, telefono, email, note) vengono trasmessi via email e trattati per gestire la tua richiesta.</li>
    <li><b>Modulo Sponsor / contatto commerciale</b>: analogamente, i dati dell'azienda e del referente (nome, email, eventuali note) vengono inviati via email per valutare la proposta di partnership.</li>
    <li><b>Preferenza cookie</b>: una piccola informazione tecnica salvata nel tuo browser (localStorage) per ricordare se hai accettato il banner. Non e' un dato identificativo e non viene trasmesso a noi.</li>
  </ul>
  <p>Non raccogliamo dati tramite newsletter, non profiliamo gli utenti e non vendiamo dati a terzi.</p>

  <h2>Finalita' e base giuridica</h2>
  <ul>
    <li>Gestire le candidature ai provini e le richieste di sponsorizzazione (base giuridica: riscontro a una tua richiesta / misure precontrattuali).</li>
    <li>Ricordare la tua scelta sui cookie (base giuridica: legittimo interesse a un corretto funzionamento del sito).</li>
  </ul>

  <h2>Conservazione dei dati</h2>
  <p>Le email ricevute tramite i moduli vengono conservate per il tempo necessario a gestire la richiesta e, se del caso, per il periodo della stagione sportiva o del rapporto con lo sponsor. Puoi chiederne la cancellazione in qualsiasi momento.</p>

  <h2>Servizi di terze parti</h2>
  <p>Il sito puo' caricare contenuti da servizi esterni che, in alcuni casi, trattano dati o impostano cookie propri. Vedi la <a href="#" onclick="route('cookies');return false;">Cookie Policy</a> per il dettaglio. Tra questi: YouTube, TikTok, Instagram, Google Maps (per video, contenuti social e mappe), oltre a Netlify (hosting) e Iubenda per le policy dell'ente.</p>

  <h2>I tuoi diritti</h2>
  <p>In base al Regolamento UE 2016/679 (GDPR) hai diritto di accedere ai tuoi dati, chiederne la rettifica o la cancellazione, limitarne od opporti al trattamento, e ricevere i dati in formato portabile. Puoi esercitare questi diritti scrivendo a <a href="mailto:privacy@custrentocalcioa5.it">privacy@custrentocalcioa5.it</a>. Hai inoltre diritto di proporre reclamo al Garante per la protezione dei dati personali (www.garanteprivacy.it).</p>

  <h2>Minori</h2>
  <p>Se sei minorenne, invia i tuoi dati tramite i moduli solo con il consenso di chi esercita la responsabilita' genitoriale.</p>

  <h2>Riferimento all'informativa ufficiale del CUS Trento</h2>
  <p>Essendo questo un sito della sezione Calcio a 5, per il trattamento dati a livello dell'ente puoi consultare anche l'informativa ufficiale del CUS Trento: <a href="https://www.iubenda.com/privacy-policy/54750032" target="_blank" rel="noopener">Privacy Policy CUS Trento</a>.</p>

  <p class="muted">Questa informativa puo' essere aggiornata nel tempo. Le modifiche saranno pubblicate su questa pagina.</p>
</div>`,"","Privacy policy del sito CUS Trento Calcio a 5.");}
