function club(){const h=state.clubHistory||{};const paragraphs=h.paragraphs||[];const imgs=h.images||[];shell("Identity","CUS Trento C5: storia e identità",`<div class="grid grid-2"><article class="card card-pad"><span class="eyebrow">Club overview</span><h2 style="font-size:34px;margin-bottom:16px">${h.title||"La nostra storia"}</h2>${paragraphs.map(p=>`<p class="muted">${p}</p>`).join("")}<div class="grid grid-2" style="margin-top:22px">${imgs.map(x=>`<article class="card"><img loading="lazy" src="${x.image}" alt="Rosa CUS Trento ${x.season}" style="height:210px;width:100%;object-fit:cover"><div class="card-pad"><span class="badge">${x.season}</span></div></article>`).join("")}</div></article><div class="grid"><div class="card card-pad" style="background:#09090b;color:white"><span class="badge">CUS Trento C5</span><h2 style="margin-top:12px">Dalla Serie D alla C1</h2><p style="color:rgba(255,255,255,.68)">Percorso sportivo, promozioni, rose storiche e identità universitaria.</p></div>${["Staff tecnico","Matchday","Archivio stagioni","Hall of fame","Contatti"].map((x,i)=>`<div class="card card-pad clickable" onclick="route('${["staff","matchday","seasons","records","contacts"][i]}')" style="background:#fff"><span class="badge">0${i+1}</span><h2 style="margin-top:12px">${x}</h2><p class="muted">Apri sezione</p></div>`).join("")}</div></div>`,"","Storia e identità CUS Trento C5.");}

function showCookie(){if(!localStorage.getItem("cus_cookie_ok"))$("#cookieBanner").classList.add("show");}
function openCookieDetails(){$("#cookieModal").classList.add("show");}
function closeCookieDetails(){$("#cookieModal").classList.remove("show");}
function acceptCookies(){localStorage.setItem("cus_cookie_ok","yes");$("#cookieBanner").classList.remove("show");}

function saveLead(type){
  const g=id=>{const el=$("#"+id);return el?el.value:"";};
  const company=g("lead_company"), pkg=g("lead_package");
  const name=g("lead_name")||g("try_name");
  const email=g("lead_email")||g("try_email");
  const role=g("try_role"), age=g("try_age"), phone=g("try_phone"), university=g("try_university"), exp=g("try_exp"), note=g("try_note")||g("lead_note");
  const subject = type==="sponsor" ? "Richiesta sponsor — "+(company||name) : "Candidatura provini — "+(name||"");
  let body="";
  if(type==="sponsor"){
    body="Azienda: "+company+"%0D%0AReferente: "+name+"%0D%0AEmail: "+email+"%0D%0APacchetto: "+pkg+"%0D%0ANote: "+note;
  } else {
    body="Nome: "+name+"%0D%0AEta': "+age+"%0D%0ARuolo: "+role+"%0D%0AUniversita'/corso: "+university+"%0D%0AEsperienza: "+exp+"%0D%0ATelefono: "+phone+"%0D%0AEmail: "+email+"%0D%0ANote: "+note;
  }
  window.location.href="mailto:info@custrentoc5.it?subject="+encodeURIComponent(subject)+"&body="+body;
}

let lightboxState={albumId:null,index:0};
function openLightbox(albumId,index){const g=(state.galleryAlbums||[]).find(x=>String(x.id)===String(albumId));if(!g||!g.photos||!g.photos.length)return;lightboxState={albumId,index};renderLightbox();$("#lightbox").classList.add("show");}
function renderLightbox(){const g=(state.galleryAlbums||[]).find(x=>String(x.id)===String(lightboxState.albumId));if(!g)return;const i=(lightboxState.index+g.photos.length)%g.photos.length;lightboxState.index=i;$("#lightboxImg").src=g.photos[i];$("#lightboxImg").alt=`${g.title} foto ${i+1}`;$("#lightboxCaption").textContent=`${g.title} — foto ${i+1} di ${g.photos.length}`;}
function moveLightbox(delta){const g=(state.galleryAlbums||[]).find(x=>String(x.id)===String(lightboxState.albumId));if(!g)return;lightboxState.index=(lightboxState.index+delta+g.photos.length)%g.photos.length;renderLightbox();}
function closeLightbox(){$("#lightbox").classList.remove("show");}
document.addEventListener("keydown",e=>{if($("#lightbox")?.classList.contains("show")){if(e.key==="Escape")closeLightbox();if(e.key==="ArrowLeft")moveLightbox(-1);if(e.key==="ArrowRight")moveLightbox(1);}});

function render(){renderNav();if(current.startsWith("gallery-album-"))galleryAlbum(current.replace("gallery-album-",""));else if(current.startsWith("article-"))articleDetail(current.replace("article-",""));else if(current.startsWith("player-"))playerDetail(current.replace("player-",""));else if(current.startsWith("match-"))matchDetail(current.replace("match-",""));else if(current==="news")news();else if(current==="squad")squad();else if(current==="fixtures")fixtures();else if(current==="coppa")coppa();else if(current==="u21")u21();else if(current==="standings")standings();else if(current==="stats")stats();else if(current==="staff")staff();else if(current==="matchday")matchday();else if(current==="gallery")gallery();else if(current==="video")videos();else if(current==="social")social();else if(current==="sponsor")sponsor();else if(current==="sponsor-lead")sponsorLead();else if(current==="tryout")tryout();else if(current==="seasons")seasons();else if(current==="timeline")timeline();else if(current==="records")records();else if(current==="contacts")contacts();else if(current==="privacy")privacy();else if(current==="cookies")cookies();else if(current==="club")club();else home();}
// ===== CMS BOOT: carica i contenuti pubblicati da content/data.json =====
async function bootData(){
  try{
    const res = await fetch(`content/data.json?v=${Date.now()}`, {cache:'no-store'});
    if(res.ok){
      const published = await res.json();
      state = hydrate(published);     // i dati pubblicati hanno priorita'
    }
  }catch(e){ /* fallback: restano i defaults gia' in state */ }
  render();
  showCookie();
}
bootData();
